'use strict';

const { ItemNotFoundError } = require('./errors');
const {
  assertNonEmptyString,
  assertNonNegativeNumber,
  assertPositiveSafeInteger,
  assertNumberInRange,
} = require('./validation');

const MIN_DISCOUNT_PERCENT = 0;
const MAX_DISCOUNT_PERCENT = 100;

/**
 * In-memory cart of named lines. Every method validates its arguments before
 * changing state, so a call that throws leaves the cart as it was.
 */
class ShoppingCart {
  constructor() {
    this.items = [];
    this.discount = 0;
  }

  /**
   * Adds a line, or adds to the quantity of the line that already has this
   * name. An existing line keeps the price it was first added with.
   * @param {string} name matched exactly, including case
   * @param {number} price unit price, 0 or greater (0 for free items)
   * @param {number} quantity whole number, 1 or greater
   * @throws {TypeError|RangeError}
   */
  addItem(name, price, quantity) {
    assertNonEmptyString(name, 'name');
    assertNonNegativeNumber(price, 'price');
    assertPositiveSafeInteger(quantity, 'quantity');

    const existing = this.items.find(i => i.name === name);
    if (existing) {
      const merged = existing.quantity + quantity;
      assertPositiveSafeInteger(merged, `merged quantity for ${JSON.stringify(name)}`);
      existing.quantity = merged;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * Removes the whole line with this name, whatever its quantity.
   * @param {string} name
   * @throws {TypeError} if name is not a non-empty string
   * @throws {ItemNotFoundError} if no line has this name
   */
  removeItem(name) {
    assertNonEmptyString(name, 'name');
    const remaining = this.items.filter(i => i.name !== name);
    if (remaining.length === this.items.length) {
      throw new ItemNotFoundError(name);
    }
    this.items = remaining;
  }

  /**
   * Sum of price × quantity over all lines, less the discount percentage.
   * Not rounded: fractional prices can carry floating-point noise.
   * @returns {number}
   */
  getTotal() {
    let subtotal = 0;
    for (const item of this.items) {
      subtotal += item.price * item.quantity;
    }
    return subtotal - (subtotal * this.discount) / 100;
  }

  /**
   * Sets the percentage taken off the total. Replaces any earlier discount.
   * @param {number} percent from 0 to 100 inclusive
   * @throws {TypeError|RangeError}
   */
  applyDiscount(percent) {
    assertNumberInRange(percent, 'discount percent', MIN_DISCOUNT_PERCENT, MAX_DISCOUNT_PERCENT);
    this.discount = percent;
  }

  /**
   * @returns {number} number of distinct lines, not the sum of their quantities
   */
  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

